      "severity": "medium",
      "file": "t19.js",
      "line": 4,
      "evidence": "hashPassword is synchronous",
      "llm_reasoning": "Performing heavy hashing synchronously in Node.js blocks the event loop, leading to potential Denial of Service (DoS) under load.",
      "suggested_fix": "Use asynchronous versions of hashing functions (e.g., bcrypt.hash) to prevent blocking the event loop."
    }
